from form_function_common import *

def add_b41(b):
    start=len(b.questions);code='B4.1'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    items=[
        ('habitat','Locating an organism','Which statement identifies a habitat rather than describing a species’ entire ecological niche?','A coastal salt marsh in which the population lives.',['Every resource used by the species and all its interactions.','Only the species’ position in a food chain.','Only the maximum temperature an enzyme can tolerate.'],'A habitat is the place or type of environment occupied; a niche also describes resource use and interactions.'),
        ('adaptation','An inherited feature','Which observation best supports describing a feature as an evolutionary adaptation?','A heritable feature improves reproductive success under particular environmental conditions.',['An individual acquires any injury during its lifetime.','Every change within an individual is inherited by its offspring.','An organism develops a feature because it consciously needs it.'],'An adaptation is heritable and contributes to fitness in the relevant environment; purposeful need is not an evolutionary mechanism.'),
        ('limiting-factor','Identifying a constraint','In a constructed experiment, adding water increases growth of a plant while adding extra light alone does not. Nutrient supply and temperature are held constant. Which conclusion is best supported?','Water availability limits growth under the tested conditions.',['Light can never limit this species in any habitat.','Every plant is limited only by water.','Water addition proves that the species cannot photosynthesize.'],'The response identifies a constraint in the tested setting, not a universal limitation across all conditions.'),
        ('tolerance-choice','Interpreting survival','Constructed survival percentages for a coastal invertebrate after a fixed exposure are 0%, 70%, 95%, 75% and 0% at salinities of 5, 15, 25, 35 and 45 g per kg, respectively. Which statement is justified?','The highest measured survival is at 25 g per kg.',['The species must be equally abundant at every salinity between 5 and 45 g per kg.','Its exact upper tolerance limit is proved to be 35 g per kg.','The experiment measures competition directly.'],'The table locates the best tested condition, but untested intermediate salinities and other ecological factors remain unresolved.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B41-'+key,title,stem,options=[ans]+wrong,reason=why)
    q('B41-dune-grass','A leaf on a dry dune','Marram grass growing on a dune can have rolled leaves with hairs and sunken stomata on the protected inner surface. Its extensive roots and rhizomes spread through the sand.',P('Explain how the leaf features can conserve water.',A('Rolling, hairs and sunken stomata shelter humid air close to the stomata.'),R('This reduces air movement and the water-vapour gradient from the leaf surface to the surrounding air, reducing transpiration.')),P('Explain a benefit of the underground structures.',A('Extensive roots can absorb water from a larger soil volume, while rhizomes anchor the plant and allow spread through unstable sand.')),P('State a possible cost of strongly restricting gas exchange.',A('Reduced carbon dioxide entry can restrict photosynthesis.')))
    q('B41-mangrove','Two problems in a mangrove habitat','The black mangrove, Avicennia germinans, secretes excess salt through leaf glands and has aerial roots called pneumatophores with internal air spaces above waterlogged mud.',P('Explain the benefit of removing excess salt.',R('Removing excess salt limits its accumulation in tissues and helps maintain conditions compatible with cell function.')),P('Explain the benefit of aerial roots and their air spaces.',A('Waterlogged mud contains little available oxygen because gas diffusion through water is slow and organisms consume oxygen.'),R('Aerial roots provide a route for oxygen from the atmosphere to submerged root tissues for aerobic respiration.')),P('Explain why an adaptation useful here may be unnecessary in a well-drained inland habitat.',A('The selective pressures differ: low root-zone oxygen and high salinity may be absent in well-drained, non-saline soil.')))
    q('B41-coral-conditions','Conditions for a shallow coral reef','Consider reef-building corals that contain photosynthetic symbionts. A proposed reef site is deep, frequently turbid, and near a river mouth with strongly fluctuating salinity.',P('Explain two constraints on photosynthesis at this site.',A('Greater depth reduces the light reaching the corals.'),A('Suspended particles in turbid water absorb or scatter light, further reducing illumination.')),P('Explain why salinity and temperature also need evaluation.',A('Salinity fluctuations can exceed the corals’ tolerance and disrupt water and ion balance.'),A('Temperature must remain within a suitable range; prolonged excessive warming can disrupt the coral–symbiont association.')),P('State why this reasoning should not be generalized to every coral species.',A('Some corals lack photosynthetic symbionts and live in deep water; the stated light dependence concerns the specified reef-building association.')))
    q('B41-coral-ph-data','Calcification under changed conditions','The following data are constructed. Fragments of one reef-building coral are maintained at the same light, temperature and salinity. Mean skeletal mass gains over a fixed period are 1.80 g at pH 8.1 and 1.17 g at pH 7.8. Lower pH can reduce carbonate availability for skeleton formation.',P('Calculate the percentage reduction in mean skeletal mass gain.',M('Use (1.80 − 1.17)/1.80 × 100.'),A('35.0% reduction.')),P('Explain a possible link between lower pH and the result using the supplied information.',R('Reduced carbonate availability can restrict calcium-carbonate skeleton formation, lowering mass gain.')),P('Explain why the means alone cannot establish the reliability of the difference.',A('Sample sizes and variation among independent coral fragments are needed; fragments from only one colony may also limit generalization.')),kind='data-based')
    climate=[('P',26,2400,'Warm throughout the year'),('Q',11,900,'Warm summers and cool winters'),('R',-1,550,'Long cold winters; short growing season')]
    q('B41-forest-biomes','Comparing forest climates','The table contains constructed long-term climate summaries. Vegetation is not shown.'+table(['Site','Mean annual temperature / °C','Annual precipitation / mm','Seasonality'],climate),P('Match P, Q and R to tropical forest, temperate forest and taiga.',A('P: tropical forest.'),A('Q: temperate forest.'),A('R: taiga.')),P('Explain why the seasonal descriptions improve the comparison over annual temperature alone.',R('Sites with the same annual mean can have different winter extremes and lengths of growing season, which affect survival and growth.')),kind='data-based')
    q('B41-open-biomes','Water, cold and open vegetation','Constructed site summaries are: U has very low rainfall and high summer temperatures; V has low precipitation, a very short cool growing season and widespread permafrost; W has moderate seasonal rainfall, extensive grasses, and recurring grazing and fire.',P('Identify the most consistent biome for each site.',A('U: hot desert.'),A('V: tundra.'),A('W: grassland.')),P('Explain why rainfall and temperature do not fully predict vegetation at W.',R('Grazing and fire can suppress tree establishment and favour grasses even where the climate alone could support more woody vegetation.')),kind='data-based')
    q('B41-saguaro','A named desert plant','The saguaro cactus, Carnegiea gigantea, grows in the Sonoran Desert. It has a water-storing stem with expandable pleats, spines instead of broad leaves, and an extensive shallow root system.',P('Relate the stem and root features to infrequent rainfall.',A('Stem storage retains water for dry intervals, and pleats accommodate changes in stored volume.'),A('Widespread shallow roots rapidly intercept water from rain near the soil surface.')),P('Explain how reduced leaf surface and a green stem form a useful combination.',R('Reduced leaves lower the exposed transpiring leaf area, while the green stem can carry out photosynthesis.')),P('Explain why these features do not imply unlimited drought tolerance.',A('Stored water is finite and the plant still loses and requires water; a sufficiently long or severe drought can exceed its tolerance.')))
    q('B41-kapok','A named rainforest tree','The kapok tree, Ceiba pentandra, can rise above surrounding tropical forest vegetation and develops broad buttresses at the base of a tall trunk.',P('Explain how height can be advantageous in a closed forest.',R('A high crown gains access to stronger light above much of the competing vegetation, supporting photosynthesis.')),P('Explain the mechanical benefit of buttresses.',A('They spread support around the trunk base and help stabilize a large tree against overturning forces.')),P('Explain one cost of this growth form.',A('Producing and maintaining a tall, supported trunk requires substantial resources, and leaves high above the roots require long-distance water transport.')))
    ph=[4,5,6,7,8];growth=[20,60,90,70,10]
    q('B41-tolerance-curve','A laboratory tolerance response','The graph shows constructed mean dry-mass gains of seedlings over the same period at five soil pH values. All other growing conditions were standardized; no competing plants were present.'+table(['Soil pH','Mean dry-mass gain / mg'],list(zip(ph,growth))),P('Identify the best tested pH and calculate the difference in gain between pH 6 and pH 8.',A('Best tested pH: 6.'),A('Difference: 80 mg.')),P('Explain why positive growth at a laboratory pH does not guarantee that the species occupies every field site at that pH.',R('Competitors, herbivores, dispersal or other abiotic conditions may prevent establishment even within the tested tolerance range.')),P('Suggest a useful improvement near the apparent optimum.',A('Test additional pH values between the existing points, with independent replicates and measures of variation.')),kind='data-based',diagram=plot(ph,growth,'Soil pH','Mean dry-mass gain / mg','Constructed seedling response across soil pH'))
    q('B41-transect','An environmental gradient','A constructed coastal transect shows lower plant cover at sites with higher soil salinity. Distance from the sea, exposure to wind and soil moisture also change along the transect.',P('Explain why this pattern alone does not establish that salinity caused the difference in cover.',R('Other variables covary with salinity, so their effects cannot be separated from the association.')),P('Describe two improvements to the field sampling.',A('Sample replicate transects or independent sites, using a consistent quadrat size and unbiased or systematic placement.'),A('Measure salinity, soil moisture and wind exposure alongside plant cover using comparable methods.')),P('Outline a complementary experiment to test a salinity effect.',A('Randomly assign similar plants to controlled salinity treatments while maintaining other conditions, with independent replication and a suitable control.')),kind='data-based')
    q('B41-factorial-limits','Changing the limiting resource','The following dry-mass gains are constructed means for comparable plants: untreated, 2.0 g; extra nutrients only, 2.1 g; extra water only, 5.0 g; extra water plus nutrients, 8.0 g. Light and temperature were matched.',P('Identify the strongest initially limiting resource indicated by these results.',A('Water: adding water causes a much larger increase than adding nutrients alone.')),P('Explain the result when both resources are added.',R('After water shortage is reduced, nutrient supply can become a stronger constraint, so supplying both permits further growth.')),P('Calculate the extra gain with both additions relative to water alone.',A('8.0 − 5.0 = 3.0 g.')),P('State why the small difference between untreated and nutrients-only plants should be treated cautiously.',A('Variation and replication are needed to determine whether the 0.1 g difference is reproducible rather than sampling noise.')),kind='data-based')
    q('B41-common-garden','Inherited difference or immediate response','In a constructed common-garden investigation, seedlings from dry-site and wet-site populations are grown under identical conditions. Mean leaf thickness remains greater in the dry-site group. The seedlings came directly from seeds collected in the wild.',P('Explain why growing both groups together is informative.',R('A common environment reduces immediate environmental differences as an explanation for the observed population difference.')),P('Explain why the result does not by itself prove a genetic adaptation.',A('Maternal effects or other inherited non-genetic differences may persist, and greater reproductive success in the dry habitat has not been demonstrated.')),P('Suggest a further test relevant to adaptation.',A('Compare offspring raised for additional generations in common conditions and test survival or reproduction of both populations in controlled dry and wet environments.')),kind='data-based')
    assert len(b.questions)-start==16

def add_b42(b):
    start=len(b.questions);code='B4.2'
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    items=[
        ('niche','An ecological role','Which description most completely represents an ecological niche?','The conditions tolerated, resources used and interactions of a species in its environment.',['Only the map coordinates of one individual.','Only the name of the biome containing the species.','Only the total number of species in an ecosystem.'],'A niche includes abiotic requirements and biotic relationships, rather than only a location.'),
        ('anaerobe','Growth with and without oxygen','A constructed culture investigation supplies all necessary nutrients. A microorganism grows without oxygen but fails to grow and is damaged by oxygen. Which description best fits the observation?','Obligate anaerobe.',['Obligate aerobe.','An organism necessarily able to thrive equally with or without oxygen.','A photoautotroph proved by this test alone.'],'The inability to tolerate oxygen distinguishes an obligate anaerobe; the test does not identify its carbon source.'),
        ('photoautotroph','Carbon and energy sources','Which pairing describes photoautotrophic nutrition?','Light as an energy source and carbon dioxide as a carbon source.',['Light as a carbon source and protein as the only energy source.','Carbon dioxide as an energy source and light as a material incorporated into biomass.','Ingestion of animals as the sole source of both carbon and energy.'],'Photoautotrophs use light energy to build organic compounds from inorganic carbon.'),
        ('saprotroph','Feeding on dead material','Which sequence best describes saprotrophic nutrition by a fungus on dead wood?','Secretion of digestive enzymes outside the organism, followed by absorption of soluble products.',['Ingestion of the entire tree into a stomach.','Absorption of sunlight as the carbon atoms in cellulose.','Photosynthesis inside every fungal hypha.'],'Saprotrophs digest organic material extracellularly and absorb smaller soluble molecules.')]
    for key,title,stem,ans,wrong,why in items:b.add(code,'B42-'+key,title,stem,options=[ans]+wrong,reason=why)
    q('B42-holozoic','Following a food particle','A small animal captures solid food and processes it in a digestive tract.',P('Distinguish ingestion, digestion and absorption.',A('Ingestion brings food into the body or digestive cavity.'),A('Digestion breaks food down into smaller molecules.'),A('Absorption moves soluble products across a surface into cells or body fluids.')),P('Distinguish egestion from excretion.',A('Egestion removes unabsorbed digestive contents; excretion removes metabolic waste produced by cells.')))
    q('B42-mixotrophy','Two routes to nutrition','A hypothetical freshwater protist contains functional chloroplasts and can also engulf bacteria. These observations define the organism for this question.',P('Explain why it is described as mixotrophic.',A('It combines autotrophic production of organic compounds using light with heterotrophic acquisition of organic material from prey.')),P('Predict how this combination could help when light becomes temporarily low but bacteria remain abundant.',R('Engulfed bacteria can supply organic carbon and energy when photosynthetic production is restricted.')),P('Suggest evidence needed before concluding that feeding fully compensates for loss of light.',A('Measure growth or reproduction in matched light and dark treatments with and without bacterial food, using independent replicates.')))
    q('B42-archaea','A domain is not a feeding category','Different archaeal species can obtain energy for ATP production from light or from chemical reactions. Some use inorganic carbon and others use organic carbon. Separately, an isolate is observed to grow both with and without oxygen.',P('Explain why Archaea should not be treated as a single nutritional category.',A('Archaea is a taxonomic domain containing organisms with diverse energy and carbon sources; membership does not specify one feeding mode.')),P('Distinguish the source of energy from the source of carbon.',A('An energy source supports processes such as ATP production; a carbon source supplies carbon atoms incorporated into organic molecules.')),P('State what the oxygen observation rules out and what it does not identify.',A('It rules out an obligate requirement for oxygen and an inability to tolerate oxygen under these conditions.'),A('It does not determine whether the organism uses light, which chemical substrate supplies energy, or its carbon source.')))
    q('B42-teeth','Inferring diet from teeth','A hominid jaw specimen has broad molar grinding surfaces and relatively small canine teeth. The specimen is described in words; no image or wear measurements are supplied.',P('Suggest a dietary inference consistent with the molars and explain it.',R('Broad grinding surfaces are consistent with processing substantial plant material by crushing or grinding it.')),P('Explain why the teeth alone do not identify one exact diet.',A('Teeth can process several food types, diets may be mixed, and morphology alone does not show the foods actually eaten.')),P('Suggest an independent source of evidence that could strengthen a dietary inference.',A('Accept dental microwear, preserved food residues/calculus, stable-isotope evidence or associated food remains, with an explanation that it provides evidence of consumed resources.')))
    q('B42-herbivore','Accessing energy in plant tissue','An herbivorous mammal has broad grinding teeth and an enlarged fermentation compartment containing microorganisms that produce cellulose-digesting enzymes.',P('Explain the contribution of the teeth.',A('Grinding breaks up plant tissue and increases the surface exposed to digestion.')),P('Explain why the microorganisms are useful.',R('They digest cellulose that the mammal cannot efficiently hydrolyse with its own enzymes.'),A('Their fermentation products can be absorbed and used by the mammal as an energy source.')),P('Explain why the association can benefit the microorganisms.',A('The compartment provides a continuing supply of substrate and a suitable habitat.')))
    q('B42-plant-defence','Physical and chemical barriers to feeding','A plant has tough leaves and produces a compound that deters a particular herbivore. Both leaf toughness and compound production require resources.',P('Explain how the two features can reduce herbivory.',A('Tough tissue is harder to penetrate or chew.'),A('A deterrent compound reduces feeding or makes the tissue less acceptable to the herbivore.')),P('Explain a possible trade-off in defence investment.',R('Resources used for defence are unavailable for other functions such as growth or reproduction, although avoided damage may offset that cost.')),P('Explain why the chemical defence may not deter every herbivore.',A('Herbivores differ in sensitivity, behaviour and detoxification ability; some specialists may tolerate the compound.')))
    q('B42-predator','A successful ambush','A predatory animal has camouflage matching vegetation, forward-facing eyes and rapid acceleration over short distances.',P('Link two features to prey capture.',A('Camouflage can reduce detection by prey before an attack.'),A('Overlapping visual fields support depth estimation, or rapid acceleration helps close a short gap before prey escape; accept either distinct second link.')),P('Explain why these features do not imply that the predator is an efficient long-distance pursuer.',R('Performance depends on context; short bursts and concealment can succeed without endurance for sustained pursuit.')))
    q('B42-prey-defence','Being hidden or being conspicuous','Prey species X is difficult to see against its background. Species Y is conspicuous, has an unpleasant defensive chemical and is avoided by predators after a harmful feeding experience.',P('Explain the different ways these features can reduce predation.',A('X reduces the chance of detection through camouflage.'),A('Y’s conspicuous appearance can act as a warning signal that predators learn to associate with its chemical defence.')),P('Explain why conspicuous colour alone does not demonstrate chemical defence in an untested species.',A('Colour may have other functions, or the species may mimic a defended species; the chemical and predator responses require evidence.')))
    q('B42-forest-light','Different routes to light','Three forest plants use different strategies: an epiphyte grows on a tree branch, a liana climbs using a supporting tree, and a shade-tolerant seedling persists on the forest floor.',P('Explain how the epiphyte and liana improve access to light.',A('Both use the supporting structure of another plant to occupy a brighter position above part of the understorey.')),P('Explain why an epiphyte is not necessarily a parasite.',A('Using a tree for physical support does not necessarily involve extracting nutrients or organic food from its living tissues.')),P('Suggest a benefit of shade tolerance and one limitation.',A('Shade tolerance permits survival with low light beneath a canopy.'),A('Growth or reproduction may remain slow when the available light limits photosynthesis.')))
    q('B42-realized-niche','Conditions alone and conditions with a competitor','The following findings are constructed. A plant establishes at pH 5, 6, 7, 8 and 9 when grown alone under otherwise suitable conditions. With a particular competitor, it establishes only at pH 7, 8 and 9.',P('Relate the two results to fundamental and realized niches.',A('The alone treatment estimates part of the fundamental niche along this pH dimension.'),A('The competitor treatment shows a more restricted realized range under the tested interaction.')),P('Explain why these results do not describe the whole niche.',R('A niche includes many other abiotic conditions, resources and interactions; only one environmental dimension and one competitor were tested.')),P('State a control needed to attribute the restriction to the competitor.',A('Keep light, water, nutrients, initial plant size and planting conditions comparable, and replicate both presence and absence treatments.')),kind='data-based')
    q('B42-competition','A changing mixed population','The table contains constructed counts of two microorganisms in mixed culture. Both use the same single limiting food resource in a uniform environment; neither consumes the other.'+table(['Day','Species A / cells','Species B / cells'],[(0,20,20),(2,35,30),(4,55,22),(6,75,8),(8,80,0)]),P('Describe the main pattern after day 2.',A('A continues to increase while B declines to zero counted cells by day 8.')),P('Explain how the pattern is consistent with competitive exclusion.',R('If both depend on the same limiting resource and A uses it more effectively, A can reduce its availability below the level needed by B.')),P('Explain the value of growing each species separately as a control.',A('Separate cultures show whether B can persist under the physical and nutritional conditions without A.')),P('State one reason not to claim that these data establish universal exclusion in nature.',A('Natural environments vary in resources and space, and unmeasured refuges or other interactions can permit coexistence; zero counted cells also depends on detection.')),kind='data-based')
    q('B42-resource-partition','Feeding at different heights','Constructed observations show three bird species feeding mainly near the ground, in the middle canopy and near the canopy top, respectively. All eat small arthropods.',P('Explain how this pattern could reduce competition.',R('Using different parts of the habitat reduces overlap in the resources encountered and consumed.')),P('Explain why the observation alone does not prove that competition caused the different feeding positions.',A('The species may differ in locomotion, predation risk or preferred prey distribution independently of current competition.')),P('Suggest evidence that would help test a competition explanation.',A('Compare feeding positions and resource use with and without the other species, using replicated natural contrasts or appropriately controlled studies.')),kind='data-based')
    assert len(b.questions)-start==16
